import type { HTTPError } from "../../error.ts";

export const kProblem = "~problem";

export interface ProblemMark {
  type?: string;
  instance?: string;
  detail?: string;
}

const reserved = /* @__PURE__ */ new Set(["type", "status", "title", "detail", "instance"]);

export function problemBody(
  error: HTTPError & { [kProblem]?: ProblemMark },
  debug?: boolean,
): Record<string, unknown> {
  const mark = error[kProblem] || {};
  const unhandled = error.unhandled;

  const extensions: Record<string, unknown> = {};
  if (!unhandled) {
    extensions.data = error.data;
    for (const key in error.body) {
      if (!reserved.has(key)) {
        extensions[key] = error.body[key];
      }
    }
  }

  return {
    ...extensions,
    type: mark.type ?? "about:blank",
    status: error.status,
    title: error.statusText ?? PHRASES[error.status],
    detail: unhandled ? undefined : mark.detail,
    instance: unhandled ? undefined : mark.instance,
    stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
  };
}

